INSERT INTO `assessment_tests` (`assessment_test_id`, `applicant_id`, `assessor_user_id`, `test_title`, `questions_json`, `scores_json`, `total_score`, `passing_score`, `result`, `test_date`, `remarks`, `created_at`, `updated_at`) VALUES
(3, 14, 1, 'Front Desk Receptionist — Job Knowledge Test', '[{\"question\":\"Handle Electrical Issue Promptly \\u2014 You have checked in a guest to their assigned room. The guest has settled in and uses an electric appliance, which causes a spark, and the electricity trips on the entire floor. What would you do?\",\"points\":20},{\"question\":\"Handle Guest Complaint With Care \\u2014 A guest complains at the front desk that their room was not cleaned before check-in, even though the system shows it as inspected. The guest is upset and other guests are waiting in line. What would you do?\",\"points\":20},{\"question\":\"Manage Overlapping Reservations \\u2014 Two guests arrive at the same time claiming the same reservation. The book shows one entry clearly, but the other guest insists they booked by phone. Both are impatient. What would you do?\",\"points\":20},{\"question\":\"Handle a Fully Booked Night \\u2014 A guest with a confirmed reservation arrives, but the hotel is fully booked due to an earlier system error. The guest is tired after a long trip. What would you do?\",\"points\":20},{\"question\":\"Support the Team During Rush Hour \\u2014 It is peak check-in time, the lobby is full, and a co-worker at the next counter is struggling with a difficult transaction while your own line is moving smoothly. What would you do?\",\"points\":20}]', '[20,20,20,20,20]', 100.00, 75.00, 'Passed', '2026-10-27', 'Auto-checked: 5/5 correct.', '2026-10-26 11:45:43', '2026-10-26 11:45:43');
